import json, sys
OUT = sys.argv[1]
FASES = int(sys.argv[2])


def M(i, fase, titulo, descricao, ativ, efeito, fatos, req, bench, hip, just, riscos, dep, ch=""):
    return dict(id=i, fase=fase, titulo=titulo, descricao=descricao, atividades=ativ, efeito=efeito, fatos=fatos,
                requisitos=req, benchmark=bench, hipotese=hip, justificativa_parametro=just, riscos=riscos,
                dependencias=dep, controle_humano=ch)


def E(tipo, ativ, c, e, o, parte=None):
    d = {"tipo": tipo, "atividades": ativ}
    if parte:
        d["parte"] = parte
    d["cenarios"] = {"conservador": c, "esperado": e, "otimista": o}
    return d


